p=argparse.ArgumentParser();p.add_argument('--case',type=Path,required=True);p.add_argument('--missions',nargs='+',required=True);a=p.parse_args();r=a.case;out=r/'MODULE_INTERFACE_AUDIT.json';assert not out.exists()
